const lessons = [
{ id:'nomen', title:'Nomen & Artikel', group:'Wörter entdecken', icon:'📦', intro:'Gib den Dingen einen Namen.', rule:'Nomen benennen Menschen, Tiere, Pflanzen, Dinge und auch Gefühle. Du schreibst sie groß. Lerne den passenden Artikel gleich mit: der, die oder das.', example:'der Fuchs · die Schule · das Abenteuer · die Freude', tip:'Die Artikel helfen dir beim Erkennen. Auch etwas, das du nicht anfassen kannst, kann ein Nomen sein: die Angst.', more:'Der, die und das sind bestimmte Artikel. Ein und eine sind unbestimmte Artikel: Ein Hund läuft vorbei. Der Hund bellt. Im Plural heißt der bestimmte Artikel immer die: die Hunde.', qs:[
['Welches Wort ist ein Nomen?',['Freude','fröhlich','freuen'],0,'Die Freude ist ein Gefühl und ein Nomen. Auch Gefühle schreiben wir groß.'],
['Welcher Artikel passt? ___ Mädchen',['der','die','das'],2,'Es heißt das Mädchen. Das grammatische Geschlecht stimmt nicht immer mit dem natürlichen Geschlecht überein.'],
['Welche Schreibweise ist richtig?',['die schöne blume','die schöne Blume','Die Schöne blume'],1,'Blume ist ein Nomen und wird großgeschrieben. schöne beschreibt die Blume.'],
['Was ist der unbestimmte Artikel zu „das Buch“?',['einer','eine','ein'],2,'Es heißt ein Buch. Ein ist hier der unbestimmte Artikel.'],
['Welche Wortgruppe steht im Plural?',['das Kind','die Kinder','ein Kind'],1,'Die Kinder sind mehrere Kinder. Plural bedeutet Mehrzahl.'],
['Ergänze den Artikel: ___ Freundschaft','die','Freundschaft ist ein Nomen. Es heißt die Freundschaft.'] ]},
{ id:'plural', title:'Einzahl & Mehrzahl', group:'Wörter entdecken',icon:'🌱',intro:'Aus einem Wort werden viele.',rule:'Singular bedeutet Einzahl: ein Hund. Plural bedeutet Mehrzahl: viele Hunde. Die Mehrzahl kann unterschiedliche Endungen haben. Manchmal ändert sich auch ein Vokal.',example:'der Baum → die Bäume · das Kind → die Kinder · das Auto → die Autos',tip:'Lerne neue Nomen als kleines Dreierpaket: der Baum, die Bäume.',more:'Häufige Pluralendungen sind -e, -er, -n, -en und -s. Manche Wörter verändern sich nicht: der Lehrer, die Lehrer. Aus a, o oder u kann ein Umlaut werden: Apfel, Äpfel.',qs:[
['Wie lautet die Mehrzahl von „das Buch“?',['die Buche','die Bücher','die Buchs'],1,'Buch wird zu Bücher. Dazu kommen der Umlaut ü und die Endung -er.'],
['Welches Wort bleibt in der Mehrzahl gleich?',['Lehrer','Kind','Blume'],0,'Der Lehrer und die Lehrer: Das Nomen bleibt gleich, der Artikel ändert sich.'],
['Welche Mehrzahl ist richtig?',['die Autos','die Auten','die Autoer'],0,'Die Mehrzahl von Auto lautet Autos.'],
['Was bedeutet Singular?',['Mehrzahl','Vergangenheit','Einzahl'],2,'Singular heißt Einzahl: ein einzelnes Ding oder Lebewesen.'],
['Schreibe die Mehrzahl: die Blume → die ___','Blumen','Bei Blume wird ein -n angehängt: die Blumen.'],
['Schreibe die Mehrzahl: das Haus → die ___','Häuser','Haus wird zu Häuser. Aus au wird äu, und -er kommt dazu.']]},
{ id:'verben',title:'Verben & Personen',group:'Wörter entdecken',icon:'⚡',intro:'Bring Bewegung in deine Sätze.',rule:'Verben sagen, was jemand tut oder was geschieht. Die Grundform heißt Infinitiv: spielen. Im Satz passt sich die Verbform an die Person an: ich spiele, du spielst.',example:'ich lerne · du lernst · er lernt · wir lernen · ihr lernt · sie lernen',tip:'Frage: Was tut jemand? Bei „Mia springt“ ist springt das Verb.',more:'Auch sein, haben und werden sind Verben. Einige Formen sind unregelmäßig: ich bin, du bist, er ist. Bei manchen Verben ändert sich der Stamm: ich lese, du liest.',qs:[
['Welches Wort ist das Verb? „Der Fuchs rennt schnell.“',['Fuchs','rennt','schnell'],1,'rennt sagt, was der Fuchs tut. Die Grundform lautet rennen.'],
['Ergänze: „Du ___ ein Buch.“',['lesen','lese','liest'],2,'Die Form für du heißt liest. Das e verändert sich zu ie.'],
['Welche Form passt zu „wir“?',['spielen','spielt','spielst'],0,'Wir spielen: Zu wir gehört hier die Endung -en.'],
['Wie heißt die Grundform von „läuft“?',['lief','laufen','gelaufen'],1,'Die Grundform heißt laufen. läuft ist eine gebeugte Form.'],
['Ergänze: „Ich ___ müde.“','bin','Das Verb sein ist unregelmäßig: ich bin, du bist, er ist.'],
['Ergänze: „Ihr ___ im Garten.“ (spielen)','spielt','Bei ihr lautet die Form spielt.']]},
{ id:'adjektive',title:'Adjektive',group:'Wörter entdecken',icon:'🎨',intro:'Mach deine Sprache bunter.',rule:'Adjektive beschreiben, wie jemand oder etwas ist: mutig, weich, spannend. Viele Adjektive kannst du steigern. So vergleichst du Dinge miteinander.',example:'schnell → schneller → am schnellsten',tip:'Frage: Wie ist etwas? Der Weg ist lang. lang ist ein Adjektiv.',more:'Die Grundstufe heißt Positiv, die Vergleichsstufe Komparativ, die höchste Stufe Superlativ. Es gibt Sonderformen: gut, besser, am besten. Bei Gleichheit nutzt du so … wie, bei Ungleichheit die Vergleichsform mit als.',qs:[
['Welches Wort beschreibt eine Eigenschaft?',['springen','Abenteuer','spannend'],2,'spannend beschreibt, wie etwas ist. Es ist ein Adjektiv.'],
['Wie steigerst du „gut“?',['guter','besser','mehr gut'],1,'gut hat eine besondere Steigerung: besser, am besten.'],
['Was passt? „Der Turm ist höher ___ das Haus.“',['wie','als','und'],1,'Nach der Vergleichsform höher steht als.'],
['Welche Reihe ist richtig?',['klein, kleiner, am kleinsten','klein, kleinig, am klein','klein, mehr klein, kleinst'],0,'klein, kleiner, am kleinsten sind die drei Steigerungsstufen.'],
['Ergänze: „Das Kissen ist so weich ___ die Decke.“','wie','Bei Gleichheit verwenden wir so … wie.'],
['Schreibe die Vergleichsstufe von „laut“.','lauter','Die Vergleichsstufe lautet lauter.']]},
{ id:'pronomen',title:'Pronomen',group:'Wörter entdecken',icon:'💬',intro:'Kleine Wörter, große Helfer.',rule:'Pronomen können Nomen ersetzen oder begleiten. Personalpronomen sind zum Beispiel ich, du, er, sie, es, wir, ihr und sie. Sie helfen dir, Wiederholungen zu vermeiden.',example:'Mia liest. Sie liest gern. · Das Buch ist spannend. Es ist neu.',tip:'Achte darauf, auf welches Nomen sich das Pronomen bezieht.',more:'Possessivpronomen zeigen eine Zugehörigkeit an: mein Heft, deine Tasche, unser Hund. Im Satz verändert sich die Form: mein Hund, mit meinem Hund. Die höfliche Anrede Sie wird großgeschrieben.',qs:[
['Ersetze „das Kaninchen“: „___ frisst.“',['Er','Es','Wir'],1,'Das Kaninchen wird durch es ersetzt.'],
['Welches Wort zeigt Zugehörigkeit?',['mein','laufen','heute'],0,'mein zeigt, wem etwas zugeordnet ist: mein Heft.'],
['Ersetze „Ben und ich“: „___ spielen.“',['Ihr','Er','Wir'],2,'Ben und ich sind zusammen wir.'],
['Welches Pronomen ersetzt „die Kinder“?',['es','sie','er'],1,'Mehrere Kinder werden mit sie bezeichnet.'],
['Ergänze: „Lina malt. ___ malt einen Drachen.“','Sie','Lina wird durch sie ersetzt. Am Satzanfang schreiben wir Sie groß.'],
['Was ist ein Personalpronomen?',['dein','ihr','schön'],1,'ihr ist hier das Personalpronomen für mehrere angesprochene Personen.']]},
{ id:'faelle',title:'Die vier Fälle',group:'Sätze verstehen',icon:'🔎',intro:'Werde zum Frage-Detektiv.',rule:'Nomen und ihre Begleiter stehen im Satz in einem Fall. Frage danach: Nominativ = Wer oder was? Genitiv = Wessen? Dativ = Wem? Akkusativ = Wen oder was?',example:'Der Hund (Wer?) bringt dem Kind (Wem?) den Ball (Wen oder was?).',tip:'Frage immer mit dem ganzen Satz: Wem bringt der Hund den Ball? Dem Kind.',more:'Beim männlichen Artikel erkennst du die vier Fälle gut: der Hund, des Hundes, dem Hund, den Hund. Beispiel Genitiv: Das Fell des Hundes ist weich. Wessen Fell? Des Hundes.',qs:[
['„Der Fuchs schläft.“ In welchem Fall steht „der Fuchs“?',['Dativ','Nominativ','Genitiv'],1,'Wer schläft? Der Fuchs. Die Frage wer oder was zeigt den Nominativ.'],
['„Ich helfe dem Kind.“ Welche Frage passt?',['Wem helfe ich?','Wen helfe ich?','Wessen helfe ich?'],0,'Wem helfe ich? Dem Kind. Das ist der Dativ.'],
['„Mia sieht den Hund.“ Welcher Fall ist „den Hund“?',['Genitiv','Dativ','Akkusativ'],2,'Wen oder was sieht Mia? Den Hund. Das ist der Akkusativ.'],
['„Das Fahrrad des Jungen ist neu.“ Welcher Fall ist „des Jungen“?',['Nominativ','Genitiv','Dativ'],1,'Wessen Fahrrad ist neu? Das Fahrrad des Jungen. Das ist der Genitiv.'],
['Ergänze: „Ich gebe ___ Mann ein Buch.“',['der','den','dem'],2,'Wem gebe ich ein Buch? Dem Mann. Deshalb brauchst du dem.'],
['Wie lautet die Frage nach dem Dativ?','Wem','Nach dem Dativ fragst du mit wem.']]},
{ id:'satzglieder',title:'Satzglieder',group:'Sätze verstehen',icon:'🧩',intro:'Entdecke die Bausteine im Satz.',rule:'Ein Satz besteht aus Satzgliedern. Das Subjekt sagt, wer oder was etwas tut. Das Prädikat enthält das Verb. Objekte ergänzen den Satz. Angaben nennen zum Beispiel Zeit und Ort.',example:'Mia | liest | am Abend | ein Buch. Wer? Mia. Was tut sie? Sie liest.',tip:'Mit der Umstellprobe erkennst du Wortgruppen: „Am Abend liest Mia ein Buch.“ Am Abend bleibt zusammen.',more:'Das Prädikat kann aus mehreren Teilen bestehen: Mia hat ein Buch gelesen. hat … gelesen gehört zusammen. Zeitangaben beantworten wann, Ortsangaben wo, wohin oder woher. Im Aussagesatz steht die gebeugte Verbform an zweiter Satzgliedstelle.',qs:[
['Was ist das Subjekt? „Der kleine Hund bellt laut.“',['bellt','Der kleine Hund','laut'],1,'Wer bellt? Der kleine Hund. Die ganze Wortgruppe ist das Subjekt.'],
['Was ist das Prädikat? „Mia hat ein Bild gemalt.“',['hat … gemalt','ein Bild','Mia'],0,'hat und gemalt bilden zusammen das zweiteilige Prädikat.'],
['Welche Frage passt zu „am Morgen“?',['Wo?','Wem?','Wann?'],2,'Am Morgen ist eine Zeitangabe und beantwortet wann.'],
['Welche Umstellung ist richtig?',['Im Garten die Kinder spielen.','Im Garten spielen die Kinder.','Spielen im die Kinder Garten.'],1,'Die Wortgruppe im Garten bleibt zusammen. spielen steht an zweiter Satzgliedstelle.'],
['Welches Satzglied antwortet auf „Wer oder was?“?','Subjekt','Das Subjekt ist der Satzgegenstand. Du findest es mit wer oder was.'],
['„Lina besucht ihren Freund.“ Was ist „ihren Freund“?',['Dativobjekt','Akkusativobjekt','Subjekt'],1,'Wen besucht Lina? Ihren Freund. Das ist das Akkusativobjekt.']]},
{ id:'zeiten',title:'Zeitformen',group:'Sätze verstehen',icon:'⏳',intro:'Reise durch gestern, heute und morgen.',rule:'Zeitformen zeigen, wie wir eine Handlung zeitlich einordnen. Präsens: ich spiele. Präteritum: ich spielte. Perfekt: ich habe gespielt. Futur I: ich werde spielen.',example:'Heute lese ich. · Gestern las ich. · Ich habe gelesen. · Ich werde lesen.',tip:'Das Perfekt hat zwei Teile: haben oder sein und das Partizip II, zum Beispiel habe gelernt oder bin gelaufen.',more:'Das Präteritum kommt oft in Erzählungen vor. Im Gespräch nutzen wir häufig das Perfekt. Das Plusquamperfekt beschreibt etwas, das vor einem vergangenen Ereignis passiert ist: Ich hatte gegessen, bevor ich losging. Auch Präsens kann Zukunft ausdrücken: Morgen fahre ich nach Berlin.',qs:[
['Welche Zeitform ist „Ich habe gelacht“?',['Präsens','Perfekt','Futur I'],1,'habe und gelacht bilden das Perfekt.'],
['Welche Form steht im Präteritum?',['ich ging','ich gehe','ich bin gegangen'],0,'ging ist die Präteritumform von gehen.'],
['Ergänze das Perfekt: „Ich ___ nach Hause gegangen.“',['habe','werde','bin'],2,'gehen bildet das Perfekt mit sein: Ich bin gegangen.'],
['Wie lautet das Futur I von „ich lerne“?',['ich habe gelernt','ich werde lernen','ich lernte'],1,'Futur I wird mit werden und der Grundform gebildet.'],
['Welche Zeitform ist „Ich hatte gegessen“?',['Plusquamperfekt','Präteritum','Präsens'],0,'hatte gegessen steht im Plusquamperfekt: der Vorvergangenheit.'],
['Schreibe das Präteritum: „Ich ___ ein Buch.“ (lesen)','las','Die Präteritumform von lesen lautet las.']]},
{ id:'praepositionen',title:'Präpositionen',group:'Sätze verstehen',icon:'🧭',intro:'Finde deinen Platz in der Sprache.',rule:'Präpositionen zeigen Beziehungen, zum Beispiel einen Ort oder eine Zeit: auf, unter, neben, mit, nach, vor. Sie bestimmen den Fall der folgenden Wortgruppe.',example:'mit dem Freund · für den Freund · auf dem Tisch · auf den Tisch',tip:'mit steht immer mit Dativ: mit wem? Mit dem Freund. für steht mit Akkusativ: für wen? Für den Freund.',more:'Wechselpräpositionen sind an, auf, hinter, in, neben, über, unter, vor, zwischen. Bei einem Ort (wo?) steht Dativ, bei einem Ziel (wohin?) Akkusativ: Das Buch liegt auf dem Tisch. Ich lege es auf den Tisch. Entscheidend ist der Orts- oder Zielbezug, nicht allein eine Bewegung.',qs:[
['Was passt? „Ich fahre mit ___ Bus.“',['den','dem','der'],1,'mit verlangt den Dativ: mit dem Bus.'],
['„Das Buch liegt auf dem Tisch.“ Welche Frage passt?',['Wohin?','Wessen?','Wo?'],2,'Wo liegt das Buch? Auf dem Tisch. Der Ort steht hier im Dativ.'],
['Ergänze: „Ich lege das Buch auf ___ Tisch.“',['den','dem','des'],0,'Wohin lege ich es? Auf den Tisch. Das Ziel steht hier im Akkusativ.'],
['Welche Wortgruppe ist richtig?',['für dem Hund','für der Hund','für den Hund'],2,'für verlangt den Akkusativ: für den Hund.'],
['Welches Wort ist eine Präposition?',['unter','blau','springen'],0,'unter ist eine Präposition und beschreibt hier eine räumliche Beziehung.'],
['Ergänze: „Ich spiele mit ___ Kind.“','dem','mit verlangt Dativ: mit dem Kind.']]},
{ id:'saetze',title:'Satzarten & Satzzeichen',group:'Sicher schreiben',icon:'✍️',intro:'Gib deinen Gedanken eine Form.',rule:'Ein Aussagesatz endet mit einem Punkt. Eine Frage endet mit einem Fragezeichen. Eine nachdrückliche Aufforderung oder ein Ausruf kann mit einem Ausrufezeichen enden.',example:'Du kommst mit. · Kommst du mit? · Komm bitte mit!',tip:'Lies den Satz laut. Erzählt er etwas, fragt er etwas oder fordert er zu etwas auf?',more:'Bei einer Ja-Nein-Frage steht die gebeugte Verbform vorn: Kommst du mit? Bei einer W-Frage steht das Fragewort vorn: Wann kommst du? Haupt- und Nebensätze trennst du mit einem Komma. Im Nebensatz mit weil steht die gebeugte Verbform am Ende.',qs:[
['Welches Zeichen passt? „Wo liegt mein Heft___“',['.','?',','],1,'Wo leitet eine Frage ein. Deshalb steht am Ende ein Fragezeichen.'],
['Welche Frage ist richtig gebaut?',['Du kommst wann?','Wann kommst du?','Wann du kommst?'],1,'In dieser W-Frage steht wann zuerst, danach das Verb kommst.'],
['Welcher Satz ist richtig?',['Ich bleibe drinnen weil es regnet.','Ich bleibe drinnen, weil es regnet.','Ich, bleibe drinnen weil es regnet.'],1,'Vor dem Nebensatz mit weil steht ein Komma.'],
['Wie endet der Nebensatz? „Ich freue mich, weil …“',['heute ich Geburtstag habe.','ich habe heute Geburtstag.','ich heute Geburtstag habe.'],2,'Im weil-Nebensatz steht das gebeugte Verb habe am Ende.'],
['Setze das Satzzeichen: „Komm sofort zurück___“','!','Die nachdrückliche Aufforderung wird hier mit einem Ausrufezeichen betont.'],
['Welcher Satz ist ein Aussagesatz?',['Wo ist Mia?','Mia ist im Garten.','Komm her!'],1,'Mia ist im Garten. Dieser Satz teilt etwas mit.']]},
{ id:'gross',title:'Groß- & Kleinschreibung',group:'Sicher schreiben',icon:'🔠',intro:'Entdecke die großen Anfangsbuchstaben.',rule:'Am Satzanfang schreibst du groß. Nomen und Eigennamen schreibst du ebenfalls groß. Manchmal werden Verben oder Adjektive wie Nomen benutzt. Dann schreibt man sie groß.',example:'Das Lesen macht Spaß. · Beim Spielen lachen wir. · Etwas Schönes passiert.',tip:'beim bedeutet bei dem. Der versteckte Artikel hilft: beim Spielen.',more:'Artikel und Wörter wie etwas, nichts oder viel können auf ein als Nomen verwendetes Wort hinweisen: das Gute, etwas Neues. Aber achte auf den Zusammenhang: das schnelle Laufen. Hier bleibt schnelle klein, Laufen ist das Nomen.',qs:[
['Welcher Satz ist richtig?',['das Kind lacht.','Das kind lacht.','Das Kind lacht.'],2,'Das steht am Satzanfang. Kind ist ein Nomen. Beide beginnen groß.'],
['Was passt? „Das ___ macht Spaß.“',['schwimmen','Schwimmen','schwimmend'],1,'Nach das wird Schwimmen hier als Nomen verwendet.'],
['Welche Schreibweise ist richtig?',['beim lesen','beim Lesen','Beim lesen'],1,'beim bedeutet bei dem. Lesen wird als Nomen verwendet.'],
['Was passt? „Ich wünsche dir etwas ___.“',['Gutes','gutes','gut'],0,'Gutes wird nach etwas hier als Nomen verwendet.'],
['Korrigiere nur das Nomen: „der hund“ → der ___','Hund','Hund ist ein Nomen und beginnt mit einem Großbuchstaben.'],
['Welche Wortgruppe ist richtig?',['das schnelle laufen','das Schnelle Laufen','das schnelle Laufen'],2,'schnelle beschreibt das Laufen. Laufen wird als Nomen benutzt.']]},
{ id:'verbindungen',title:'Sätze verbinden',group:'Sicher schreiben',icon:'🔗',intro:'Erzähle mehr mit deinen Sätzen.',rule:'Bindewörter heißen Konjunktionen. Sie verbinden Wörter oder Sätze: und, oder, aber, weil, dass. Mit weil erklärst du einen Grund. Mit aber zeigst du einen Gegensatz.',example:'Ich übe, weil ich sicherer werden möchte. · Ich bin müde, aber ich lese noch.',tip:'Nach weil und dass steht die gebeugte Verbform am Ende des Nebensatzes.',more:'Vor aber sowie vor Nebensätzen mit weil oder dass setzt du ein Komma. Bei einfachen Verbindungen mit und oder oder steht meist kein Komma. Unterscheide das und dass: das ist oft ein Artikel oder Pronomen; dass leitet einen Nebensatz ein.',qs:[
['Welches Bindewort nennt einen Grund?',['oder','weil','aber'],1,'weil erklärt den Grund für etwas.'],
['Ergänze: „Ich möchte kommen, ___ ich habe keine Zeit.“',['aber','weil','dass'],0,'aber zeigt den Gegensatz zwischen dem Wunsch und der fehlenden Zeit.'],
['Welche Schreibweise ist richtig?',['Ich hoffe, das du kommst.','Ich hoffe dass, du kommst.','Ich hoffe, dass du kommst.'],2,'dass leitet den Nebensatz ein. Das Komma steht davor.'],
['Was passt? „Das ist ___ Buch, das ich suche.“',['dass','das','dem'],1,'Vor Buch steht der Artikel das.'],
['Verbinde mit einem Grund: „Ich trinke, ___ ich Durst habe.“','weil','weil leitet den Grund ein. habe steht am Ende des Nebensatzes.'],
['Welcher Satz ist richtig?',['Ich lese und Mia malt.','Ich lese, und, Mia malt.','Ich lese und, Mia malt.'],0,'Diese einfache Verbindung mit und braucht kein Komma.']]}
];
if(typeof module!=='undefined') module.exports=lessons;
